CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS content_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),content_type TEXT NOT NULL CHECK (content_type IN ('page','solution','industry','platform','customer','resource','capability')),slug TEXT NOT NULL UNIQUE,title TEXT NOT NULL,summary TEXT NOT NULL,body JSONB NOT NULL DEFAULT '{}'::jsonb,published BOOLEAN NOT NULL DEFAULT FALSE,published_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),search_vector TSVECTOR GENERATED ALWAYS AS (to_tsvector('english', coalesce(title,'') || ' ' || coalesce(summary,''))) STORED,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS content_items_type_published_idx ON content_items (content_type,published,published_at DESC); CREATE INDEX IF NOT EXISTS content_items_search_idx ON content_items USING GIN(search_vector);
CREATE TABLE IF NOT EXISTS locations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),region TEXT NOT NULL,city TEXT NOT NULL,label TEXT NOT NULL,address TEXT,latitude NUMERIC(9,6),longitude NUMERIC(9,6),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(region,city,label));
CREATE TABLE IF NOT EXISTS contact_submissions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),first_name TEXT NOT NULL CHECK(char_length(first_name)<=120),last_name TEXT NOT NULL CHECK(char_length(last_name)<=120),company TEXT NOT NULL CHECK(char_length(company)<=240),email TEXT NOT NULL CHECK(char_length(email)<=320),country TEXT NOT NULL CHECK(char_length(country)<=120),reason TEXT NOT NULL CHECK(char_length(reason)<=200),message TEXT NOT NULL DEFAULT '' CHECK(char_length(message)<=4000),marketing_consent BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS contact_submissions_created_idx ON contact_submissions(created_at DESC); CREATE INDEX IF NOT EXISTS contact_submissions_email_idx ON contact_submissions(lower(email));
CREATE TABLE IF NOT EXISTS newsletter_subscriptions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),email TEXT NOT NULL UNIQUE CHECK(char_length(email)<=320),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','unsubscribed')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS request_idempotency (idempotency_key TEXT PRIMARY KEY CHECK(char_length(idempotency_key) BETWEEN 8 AND 200),expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()); CREATE INDEX IF NOT EXISTS request_idempotency_expires_idx ON request_idempotency(expires_at);
